{
  // CSD_RATIONALE_BEGIN
  // Perform at most one verified decoding step when maxSteps > 0, preserving
  // constrained-span invariants. In unconstrained mode, bias toward opening a
  // constrained span around symbolic quantities by boosting "<<" and also bias
  // toward EOS after likely answer endings in a short recent window. In
  // constrained mode, use a constrained helper step and only close the span
  // from a branch where parser completeness is explicitly established.
  // This guarantees observable progress whenever maxSteps > 0.
  // CSD_RATIONALE_END
  generated := generatedPrefix;
  insideConstrainedOut := insideConstrained;
  currentConstrainedOut := currentConstrained;
  cost := 0;
  var steps := 0;

  if 0 < maxSteps {
    if insideConstrainedOut {
      var next := helpers.RepetitionPenaltyStep(lm, parser, prompt, currentConstrainedOut, generated, 1.5, eosToken);
      steps := steps + 1;
      if next == eosToken {
      } else {
        var validNext := helpers.IsTokenValidNext(parser, currentConstrainedOut, next);
        if validNext {
          generated, insideConstrainedOut, currentConstrainedOut := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, next);
          var completeNow := parser.IsCompletePrefix(currentConstrainedOut);
          if completeNow {
            generated, insideConstrainedOut, currentConstrainedOut := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
          }
        } else {
          var stablePrefix := generated[..|generated| - |currentConstrainedOut|];
          generated, currentConstrainedOut := helpers.RollbackConstrainedSpan(parser, stablePrefix, generated, currentConstrainedOut);
          insideConstrainedOut := false;
        }
      }
    } else {
      lm.GenerateLogits(prompt + generated);
      helpers.BoostTokenLogits(lm, ["<<"], 8.0);
      if 0 < |generated| {
        if generated[|generated| - 1] == "." || generated[|generated| - 1] == "!" || generated[|generated| - 1] == "?" {
          helpers.BoostTokenLogits(lm, [eosToken], 8.0);
        }
      }
      if 1 < |generated| {
        if generated[|generated| - 2] == "." || generated[|generated| - 2] == "!" || generated[|generated| - 2] == "?" {
          helpers.BoostTokenLogits(lm, [eosToken], 3.0);
        }
      }
      var next := lm.ChooseNextTokenUnconstrained();
      steps := steps + 1;
      if next == eosToken {
      } else {
        if next == "<<" {
          generated, insideConstrainedOut, currentConstrainedOut := helpers.OpenConstrainedSpan(lm, generated);
        } else {
          generated := generated + [next];
        }
      }
    }
  }

  cost := steps;
}

